      <div className="side-foot"><div style={{ color: '#dbe5dc', fontSize: 11, fontWeight: 700, padding: '4px 4px 10px' }}>Signed in</div><div style={{ color: '#91ada2', fontSize: 10, overflow: 'hidden', textOverflow: 'ellipsis' }}>{userId || 'Store team member'}</div><button className="nav-link" style={{ marginTop: 11, width: '100%', border: 0, background: 'transparent', textAlign: 'left' }} onClick={() => signOut({ redirectUrl: basePath || '/' })}><LogOut size={15} /> Sign out</button></div>
